            "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/KhivaWalls.jpg/1280px-KhivaWalls.jpg",
            "file": "KhivaWalls.jpg",
            "author": "Doron",
            "license": "CC BY-SA 3.0",
            "licenseUrl": "http://creativecommons.org/licenses/by-sa/3.0/",
